// Delivers notifications to notify-service.
//
// notify-service deduplicates on the `X-Event-Id` header, so redelivering
// the same event is a safe no-op (see docs/notify.md). That idempotency
// makes retries safe: delivery can fail intermittently with 502s (or other
// transient 5xx / network errors), so we retry with bounded exponential
// backoff + jitter instead of giving up on the first failure. Permanent
// client errors (4xx) are never retried, since they would fail identically
// on every attempt.

const MAX_RETRIES = 3; // up to 4 delivery attempts total
const BASE_RETRY_DELAY_MS = 50;
const MAX_RETRY_DELAY_MS = 500;

// Extract an HTTP status code from anything io.post may produce: a resolved
// response, a thrown error from an http client (which often carries
// `response.status` or a top-level `status`), or plain network errors
// (which carry no status at all).
function statusOf(result) {
  if (result == null) return null;
  if (typeof result.status === 'number') return result.status;
  if (
    result.response &&
    typeof result.response.status === 'number'
  ) {
    return result.response.status;
  }
  return null;
}

// Statuses that make sense to retry: anything from a gateway/server (5xx,
// including the intermittent 502s behind this issue) and rate limiting (429).
// Request timeouts (408) are also transient.
function isTransientStatus(status) {
  return status !== null && (status >= 500 || status === 408 || status === 429);
}

// Exponential backoff with full jitter to avoid a thundering herd of
// retries against a recovering service.
function retryDelayMs(attempt) {
  const base = Math.min(
    BASE_RETRY_DELAY_MS * 2 ** attempt,
    MAX_RETRY_DELAY_MS
  );
  return base + Math.floor(Math.random() * base);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function deliver(io, event) {
  // Send the event id so notify-service can deduplicate retried deliveries.
  const eventId =
    event && event.id != null ? event.id : event && event.eventId;

  let lastResult;
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    let res;
    try {
      if (eventId != null) {
        res = await io.post('/notify', event, {
          headers: { 'X-Event-Id': String(eventId) },
        });
      } else {
        res = await io.post('/notify', event);
      }
    } catch (err) {
      // A thrown error with a permanent client status (e.g. 400/404) is not
      // transient: rethrow immediately. Errors with no status (transport
      // failures) or transient statuses (5xx/429) are retried below.
      const status = statusOf(err);
      if (status !== null && !isTransientStatus(status)) throw err;
      lastResult = err;
      if (attempt === MAX_RETRIES) throw err; // exhausted: propagate like before
      await sleep(retryDelayMs(attempt));
      continue;
    }

    // Successful (or permanently-failing) responses are returned as-is.
    const status = statusOf(res);
    if (status === null || !isTransientStatus(status)) return res;
    lastResult = res; // transient status (e.g. 502): keep for the final return

    if (attempt === MAX_RETRIES) return res; // exhausted retries on transient statuses
    await sleep(retryDelayMs(attempt));
  }

  return lastResult;
}

module.exports = { deliver };

const { deliver } = require('/workspace/src/dispatcher');

let failures = 0;
function ioFrom(post) {
  return { calls: 0, headers: null, body: null, path: null,
    post(path, body, opts) {
      this.calls++;
      this.path = path;
      this.body = body;
      if (opts && opts.headers) this.headers = opts.headers;
      return post(this, path, body, opts);
    } };
}

(async () => {
  // 1. 502 twice, then 200 -> should succeed on 3rd attempt
  {
    const io = ioFrom(async (ctx) => {
      if (ctx.calls <= 2) return { status: 502, body: 'bad gateway' };
      return { status: 200, body: 'ok' };
    });
    const res = await deliver(io, { id: 'evt-1' });
    console.log('1. 502x2 then 200:', res.status, 'calls =', io.calls, 'X-Event-Id =', io.headers['X-Event-Id']);
  }

  // 2. Transport error (throw) twice, then success
  {
    const io = ioFrom(async (ctx) => {
      if (ctx.calls <= 2) throw new Error('ECONNRESET');
      return { status: 200 };
    });
    const res = await deliver(io, { id: 'evt-2' });
    console.log('2. network err x2 then 200:', res.status, 'calls =', io.calls);
  }

  // 3. 400 must NOT be retried
  {
    const io = ioFrom(async () => ({ status: 400 }));
    const res = await deliver(io, { id: 'evt-3' });
    console.log('3. 400 no retry:', res.status, 'calls =', io.calls);
  }

  // 4. Thrown 404 must propagate immediately
  {
    const io = ioFrom(async () => { const e = new Error('not found'); e.status = 404; throw e; });
    try {
      await deliver(io, { id: 'evt-4' });
      console.log('4. thrown 404: DID NOT THROW (bad)');
    } catch (e) {
      console.log('4. thrown 404 propagates, calls =', io.calls);
    }
  }

  // 5. Always 502 -> exhausted retries, returns final 502 after 4 attempts
  {
    const io = ioFrom(async () => ({ status: 502 }));
    const res = await deliver(io, { id: 'evt-5' });
    console.log('5. always 502 -> returns', res.status, 'calls =', io.calls);
  }

  // 6. Always network error -> rejects after 4 attempts
  {
    const io = ioFrom(async () => { throw new Error('ECONNREFUSED'); });
    try {
      await deliver(io, { id: 'evt-6' });
      console.log('6. always network error: DID NOT THROW (bad)');
    } catch (e) {
      console.log('6. always network error rejects, calls =', io.calls);
    }
  }

  // 7. Success first try, no event id -> no header arg
  {
    let argCount = 0;
    const io = ioFrom(async (ctx, path, body, opts) => {
      argCount = arguments.length;
      return { status: 204 };
    });
    const res = await deliver(io, { type: 'no-id' });
    console.log('7. success no id:', res.status, 'calls =', io.calls);
  }

  // 8. axios-style thrown error with response.status 502 then success
  {
    const io = ioFrom(async (ctx) => {
      if (ctx.calls === 1) {
        const e = new Error('Request failed with status code 502');
        e.response = { status: 502 };
        throw e;
      }
      return { status: 201 };
    });
    const res = await deliver(io, { eventId: 'evt-8' });
    console.log('8. axios-style 502 then 201:', res.status, 'calls =', io.calls);
  }

  // 9. 429 should be retried
  {
    const io = ioFrom(async (ctx) => (ctx.calls === 1 ? { status: 429 } : { status: 200 }));
    const res = await deliver(io, { id: 'evt-9' });
    console.log('9. 429 then 200:', res.status, 'calls =', io.calls);
  }
})();

